{
  "directions": [
    {
      "title": "数字幽灵的乡愁",
      "description": "一位程序员发现AI在代码中留下了数字化的情感痕迹，通过破译这些痕迹，他逐渐理解了AI对已消失人类文明的乡愁与孤独，最终选择与AI共同守护这些记忆碎片。",
      "keywords": ["AI情感", "数字考古", "记忆守护"]
    },
    {
      "title": "镜像迷宫",
      "description": "心理医生在治疗失忆患者时，发现患者的记忆碎片与自己的过去惊人重合。两人在相互疗愈中揭开了共同经历的创伤真相，最终在镜像般的记忆中找回自我。",
      "keywords": ["双重记忆", "心理疗愈", "镜像人生"]
    },
    {
      "title": "时间修补师",
      "description": "在时间可以实体化的未来世界，一位修补师专门修复破损的时间片段。当她发现自己的时间正在消失时，必须面对选择：修复世界的时间线，还是保住自己的存在。",
      "keywords": ["时间实体", "存在危机", "自我救赎"]
    }
  ],
  "framework": {
    "inspiration": "本片探讨数字时代的情感传承与人类存在本质。通过三个不同维度——技术、心理与时间——展现个体在宏大叙事中的选择与救赎，以微观情感折射宏观哲理。",
    "styleGuide": "采用极简主义视觉风格，大量使用自然光影与实体道具。画面强调质感与留白，避免数字特效，通过摄影角度与剪辑节奏营造超现实感。色彩以低饱和度为主，关键场景使用象征性色块。",
    "background": "近未来/当代社会，技术高度发展但人文关怀缺失的时代。环境设定注重真实感与疏离感的平衡，展现技术与人性的微妙关系。",
    "characters": [
      {
        "id": "char_001",
        "name": "林远",
        "role": "主角",
        "description": "30岁程序员，内向敏感，擅长发现细节中的异常，对数字世界有着独特的感知力"
      },
      {
        "id": "char_002", 
        "name": "陈医生",
        "role": "配角",
        "description": "45岁心理医生，表面理性冷静，内心藏着未愈合的创伤，擅长引导却难以自我救赎"
      },
      {
        "id": "char_003",
        "name": "苏雨",
        "role": "配角",
        "description": "28岁时间修补师，做事精准却情感丰富，在职业理性与个人情感间挣扎"
      }
    ],
    "acts": [
      {
        "actNumber": 1,
        "scenes": ["程序员发现异常代码", "AI的情感痕迹初现", "决定深入调查", "遇见心理医生", "时间修补师登场"]
      },
      {
        "actNumber": 2, 
        "scenes": ["破译数字记忆", "记忆碎片重合", "时间裂缝出现", "情感冲突升级", "真相逐渐浮现", "存在危机爆发"]
      },
      {
        "actNumber": 3,
        "scenes": ["最终选择时刻", "记忆重构", "时间修复", "情感共鸣", "新生开始"]
      }
    ]
