metadata.content:
{
  "directions": [
    {
      "title": "数字记忆的考古学家",
      "description": "一位考古学家在沙漠中发现能读取人类记忆的古老服务器，通过数字碎片重构逝者意识，却在过程中与自己的记忆产生危险交融，引发身份危机。",
      "keywords": ["记忆考古", "意识融合", "身份解构"]
    },
    {
      "title": "机械心脏的调律师",
      "description": "在反乌托邦未来，一位机械心脏调律师通过维修人造器官窥见客户记忆，当她发现所有心脏都连接着同一核心意识时，必须做出道德抉择。",
      "keywords": ["机械器官", "集体意识", "伦理困境"]
    },
    {
      "title": "声音编织者",
      "description": "一位失聪作曲家通过特殊设备将城市声音转化为可见的几何图案，在编织声音图谱时发现了隐藏的城市密码，却引来了监控势力的追捕。",
      "keywords": ["通感艺术", "城市密码", "声音可视化"]
    }
  ],
  "framework": {
    "inspiration": "本片探讨数字时代人类记忆与身份的流动性。通过三个独特视角，展现技术如何重塑我们对自我认知的理解，每个故事都围绕'感知边界'展开，在微观情感与宏观社会议题间建立诗意连接。",
    "styleGuide": "采用极简主义美学与自然光影，大量使用特写镜头捕捉细微表情变化。色彩以低饱和度为主，关键记忆片段采用高对比度。避免特效，依靠摄影角度和剪辑节奏创造超现实感。",
    "background": "近未来，技术已深度融入人类感知系统。社会处于数字化转型的临界点，传统记忆方式与数字存储并存，形成独特的文化断层。",
    "characters": [
      {
        "id": "char_001",
        "name": "林远",
        "role": "主角",
        "description": "35岁记忆考古学家，理性冷静但内心孤独，对逝去妻子抱有执念"
      },
      {
        "id": "char_002", 
        "name": "陈默",
        "role": "配角",
        "description": "28岁机械心脏首席工程师，技术天才却情感疏离，逐渐觉醒自我意识"
      },
      {
        "id": "char_003",
        "name": "苏音",
        "role": "主角",
        "description": "30岁失聪作曲家，敏感细腻，通过视觉化声音感知世界，拥有独特艺术视角"
      }
    ],
    "acts": [
      {
        "actNumber": 1,
        "scenes": ["沙漠考古现场发现服务器", "首次连接数字记忆", "妻子记忆碎片浮现", "自我记忆开始混乱", "决定深入探索"]
      },
      {
        "actNumber": 2,
        "scenes": ["记忆边界模糊加剧", "发现服务器真相", "道德困境出现", "与系统对抗", "关键抉择时刻"]
      },
      {
        "actNumber": 3,
        "scenes": ["记忆重构完成", "新身份确立", "与过去和解", "开放式结局", "诗意收尾"]
      }
    ]
  },
  "rawText": "741852963"
}

