    {
      "title": "方言记忆的拓扑重构",
      "description": "一位濒危方言研究者发现语言本身具有空间拓扑能力，通过发音能重构物理空间。她在调查最后一个方言村落时，发现村民通过特定音节维持着现实结构的稳定，而外来开发商的推土机正威胁着这种脆弱平衡。",
      "keywords": ["语言考古学", "空间拓扑", "文化守护"]
    },
    {
      "title": "声音编织的时间织物",
      "description": "失聪的声音艺术家通过触觉感知到方言中的时间维度，发现每个方言词汇都编织着特定的历史时刻。当她试图录制即将消失的方言时，意外解锁了能够重现过去场景的能力，却在时间织物的裂缝中发现了被掩盖的集体创伤。",
      "keywords": ["感官替代", "时间编织", "集体记忆"]
    },
    {
      "title": "地脉共振的沉默战争",
      "description": "地质学家发现特定方言的声波频率能与地脉产生共振。当全球化语言标准化进程威胁方言多样性时，地脉开始出现异常震动。主角必须在语言学家和地质灾难预言者双重身份间抉择，拯救即将因语言统一而崩塌的地理结构。",
      "keywords": ["地质声学", "文明冲突", "生态语言学"]
    }
  ],
  "storyLength": "short",
  "storyLengthLabel": "短篇 · 3-5分钟", 
  "storyLengthDesc": "该故事适合以紧凑节奏呈现，围绕语言与空间的神秘联系这一核心概念展开，2-3幕结构最为合适。预估25-35个镜头，ASL约6-8秒。",
  "framework": {
    "inspiration": "影片探索语言不仅是交流工具，更是维系现实结构的隐秘力量。当特定方言濒临消失，其承载的空间维系功能开始崩溃，主角必须在文化保存与现实稳定间做出抉择。",
    "styleGuide": "采用冷静的观察式镜头语言，强调声音的物理质感与空间的微妙变化。色彩以大地色系为主，避免夸张的视觉特效，通过细微的环境变化表现语言力量的显现。",
    "background": "设定在当代边缘化乡村与现代化都市的交界地带，展现传统文化与现代文明的张力。时间背景为现在进行时，强调问题的紧迫性。",
    "characters": [
      {
        "id": "char_001",
        "name": "林音",
        "role": "主角",
        "description": "30岁语言人类学家，对声音极度敏感，执着于记录濒危方言，逐渐发现语言更深层的神秘属性"
      },
      {
        "id": "char_002", 
        "name": "老言",
        "role": "配角",
        "description": "最后一位纯正方言使用者，80岁，掌握着语言与空间关系的秘密，态度谨慎而神秘"
      }
    ],
    "acts": [
      {
        "actNumber": 1,
        "scenes": ["林音抵达濒危方言村落", "记录老言的发音时发现空间异常", "意识到方言的特殊力量"]
      },
      {
        "actNumber": 2, 
        "scenes": ["开发商推土机逼近村庄", "林音验证方言与空间的关联", "老言揭示语言维系现实的秘密"]
      },
      {
        "actNumber": 3,
        "scenes": ["林音在保护文化与拯救现实中抉择", "创新性运用方言力量化解危机", "留下开放式的文化存续思考"]
      }
    ]
  },
  "rawText": "地方v并具有广泛"
}

