{
  "directions": [
    {
      "title": "记忆的考古学家",
      "description": "一位历史学家的记忆开始与华国锋的记忆交织，在档案馆的尘埃中，他通过触摸文物体验1976年的关键瞬间，逐渐分不清自己是研究者还是亲历者，最终在镜像中完成身份的和解。",
      "keywords": ["记忆融合", "历史重构", "身份认同"]
    },
    {
      "title": "时间的刺绣师",
      "description": "一位女性刺绣艺术家发现自己的针线能编织时间，当她修复华国锋时期的刺绣作品时，线迹开始流动展现历史真相，她在艺术与政治的记忆张力中寻找平衡。",
      "keywords": ["织物叙事", "女性视角", "微观历史"]
    },
    {
      "title": "声音的保管员",
      "description": "声学档案管理员在整理旧录音时，发现一段从未公开的华国锋讲话，声音逐渐获得实体形态，在空荡的档案馆内游走，引导管理员重新聆听被遗忘的历史回响。",
      "keywords": ["听觉记忆", "物质性", "历史回声"]
    }
  ],
  "storyLength": "short",
  "storyLengthLabel": "短篇 · 3-5分钟",
  "storyLengthDesc": "该故事适合以紧凑节奏呈现，围绕单一人物弧线展开，2-3幕结构最为合适。预估20-40个镜头，ASL约5-7秒。",
  "framework": {
    "inspiration": "影片通过超现实手法探索历史记忆的个人化重构，以华国锋时期为历史背景，聚焦个体与集体记忆的对话关系，在微观叙事中展现宏观历史的复杂质感。",
    "styleGuide": "采用低饱和度色调，大量使用特写镜头捕捉细微表情和物体质感。避免直接历史再现，通过隐喻和象征手法表现历史记忆。画面构图强调不对称和留白。",
    "background": "设定在当代中国的档案馆、工作室等封闭空间，通过物品、声音和纹理唤起1976-1978年的历史氛围，避免直接历史场景再现。",
    "characters": [
      {
        "id": "char_001",
        "name": "林远",
        "role": "主角",
        "description": "40岁历史学者，严谨克制，对历史真相有执着追求，开始经历记忆混淆"
      }
    ],
    "acts": [
      {
        "actNumber": 1,
        "scenes": ["主角在档案馆发现异常", "首次记忆交融体验"]
      },
      {
        "actNumber": 2,
        "scenes": ["记忆混淆加剧", "通过物品追溯历史", "身份危机爆发"]
      },
      {
        "actNumber": 3,
        "scenes": ["镜像中的和解", "新的理解形成"]
      }
    ]
  },
  "rawText": "华国锋v不久过户"
}

