{
  "directions": [
    {
      "title": "意识迷宫中的时间悖论",
      "description": "理工科学生在算法竞赛中因过度疲劳陷入昏迷，意识被困在自己设计的递归程序里。他在无限循环的代码迷宫中寻找出口，却发现每个循环都对应着现实中生命体征的衰减。最终他必须破解自己创造的时间悖论，在意识彻底消散前找到回归现实的密钥。",
      "keywords": ["意识迷宫", "递归现实", "时间悖论"]
    },
    {
      "title": "记忆标本师",
      "description": "文科生在历史文献整理比赛中精神崩溃，获得了看见他人记忆具象化的能力。他发现每个人的记忆都像博物馆里的标本，而他的导师正在系统性地盗取优秀学生的创意记忆。主角必须在自己的记忆被完全抽取前，利用这种能力反制这场学术阴谋。",
      "keywords": ["记忆具象化", "学术剥削", "心理反抗"]
    },
    {
      "title": "困在数据洪流中",
      "description": "大数据竞赛选手在连续编程72小时后，开始看见现实世界的数据流动。他发现整个校园都是一个巨大的数据采集系统，学生们的行为都被量化评分。当他试图揭露这个系统时，系统开始将他标记为异常数据，展开了一场现实与数据边界模糊的生存之战。",
      "keywords": ["数据可视化", "系统反抗", "现实扭曲"]
    }
  ],
  "storyLength": "short",
  "storyLengthLabel": "短篇 · 3-5分钟",
  "storyLengthDesc": "该故事适合以紧凑节奏呈现，围绕单一人物弧线展开，2-3幕结构最为合适。预估20-40个镜头，ASL约5-7秒。",
  "framework": {
    "inspiration": "影片探讨当代学术压力下青年的精神困境，将疲惫这一生理状态转化为超现实的心理冒险。通过意识迷宫、记忆可视化、数据洪流三个维度，展现知识追求与自我保全的深刻矛盾。",
    "styleGuide": "采用冷色调现实主义与暖色调超现实场景交替的视觉语言。现实场景使用手持摄影与自然光，超现实部分采用精密构图与戏剧性打光。避免使用明显特效，通过摄影角度与剪辑节奏制造心理压迫感。",
    "background": "设定在近未来的精英大学环境，学术竞争白热化，科技监控无处不在。这是一个外表光鲜但内在异化的知识工厂，既是求知的殿堂，也是精神的牢笼。",
    "characters": [
      {
        "id": "char_001",
        "name": "林知远",
        "role": "主角",
        "description": "22岁计算机系天才学生，黑眼圈深重，穿着皱巴巴的校服。表面理性冷静，内心渴望突破系统束缚。"
      },
      {
