{
  "directions": [
    {
      "title": "敦煌神舞·时空交叠",
      "description": "大学生在敦煌石窟祈福时，千年壁画中的菩萨活化，围绕他跳起神圣舞蹈。舞蹈不仅是赐福仪式，更是跨越时空的文化传承。主角虽未察觉神迹，但内心已种下文化觉醒的种子。",
      "keywords": ["文化传承", "时空交错", "神圣舞蹈"]
    },
    {
      "title": "内心镜像·菩萨显形",
      "description": "大学生为前途迷茫而祈福，闭眼瞬间，菩萨石像化作他内心恐惧与渴望的具象化形态。神佛之舞实为心理投射，香尽时刻他获得顿悟，重新审视人生选择。",
      "keywords": ["心理投射", "自我认知", "成长顿悟"]
    },
    {
      "title": "微观宇宙·香火世界",
      "description": "当香插入香炉的瞬间，大学生被缩小至微观尺度。菩萨石像在香火缭绕中活化，舞蹈实为在香火宇宙中维持世界平衡的仪式。主角无意中见证并参与了这场维系现实与神话边界的神秘仪式。",
      "keywords": ["微观世界", "仪式魔法", "维度穿越"]
    }
  ],
  "storyLength": "short",
  "storyLengthLabel": "短篇 · 3-5分钟",
  "storyLengthDesc": "该故事适合以紧凑节奏呈现，围绕单一人物弧线展开，2-3幕结构最为合适。预估20-40个镜头，ASL约5-7秒。",
  "framework": {
    "inspiration": "影片通过大学生在敦煌祈福时与活化菩萨的无声邂逅，探讨现代人与传统文化的精神连接。神佛在香火时限内的舞蹈既是赐福仪式，也是文化记忆的苏醒，主角虽未察觉却已获得内在转变。",
    "styleGuide": "画面以敦煌壁画美学为基底，采用暖金色调与柔和光影。菩萨活化场景需保持庄严神圣感，舞蹈动作借鉴敦煌飞天姿态，避免夸张特效，通过实体拍摄与精细后期实现石像的优雅活化。",
    "background": "当代敦煌莫高窟景区，融合千年历史遗迹与现代旅游氛围。故事发生在游客稀少的傍晚时分，夕阳透过石窟缝隙，营造出神秘而宁静的时空交错感。",
    "characters": [
      {
        "id": "char_001",
        "name": "林远",
        "role": "主角",
        "description": "21岁美术系大学生，内心迷茫却对传统文化有潜在共鸣。穿着简约现代服装，背包里装着素描本，外表平静内心丰富。"
      }
    ],
    "acts": [
      {
        "actNumber": 1,
        "scenes": ["林远独自进入敦煌石窟祈福", "插香闭眼，光线渐变神秘"]
      },
      {
        "actNumber": 2,
        "scenes": ["菩萨石像缓缓活化", "神佛围绕主角跳起神圣舞蹈", "香火随时间逐渐缩短"]
      },
      {
        "actNumber": 3,
        "scenes": ["香尽时刻神佛归位", "林远睁眼离开，带着微妙变化"]
      }
    ]
  },
  "rawText": "大学生去敦煌寺庙祈福\n在插好香，闭眼双手合十后，四周的菩萨石像“活”起来了\n在浑然不知的大学生身周起舞，播撒幸福\n在最后一点香燃尽时，佛像回归原位，大学生起来，浑然不知"
}

