metadata.content:
{
  "directions": [
    {
      "title": "化学公式与人性方程式",
      "description": "一位化学教授在整理校史档案时，发现1952年合并前的各校实验笔记中隐藏着一个未完成的革命性研究。当他试图重现实验时，却引发了与当代学术伦理的激烈冲突，迫使他面对知识传承与道德边界的选择。",
      "keywords": ["学术伦理", "历史传承", "道德困境"]
    },
    {
      "title": "实验室里的时光褶皱",
      "description": "一名研究生在深夜实验室意外触发了时间异常，能够与1952年建校初期的前辈科学家进行跨时空对话。两个时代的学术理念在时空中碰撞，改变了她对科研价值的认知。",
      "keywords": ["时空对话", "学术传承", "价值重构"]
    },
    {
      "title": "配方之外",
      "description": "跟随一位老校工视角，通过他七十年来守护校园的经历，见证从化工学院到综合性大学的蜕变。当他即将退休时，发现自己珍藏的初代实验室钥匙能打开一扇被遗忘的门。",
      "keywords": ["微观史诗", "校园记忆", "时光见证"]
    }
  ],
  "storyLength": "short",
  "storyLengthLabel": "短篇 · 3-5分钟",
  "storyLengthDesc": "该故事适合以紧凑节奏呈现，围绕单一人物弧线展开，2-3幕结构最为合适。预估20-40个镜头，ASL约6-8秒。",
  "framework": {
    "inspiration": "基于华东理工大学校史，将学术传承具象化为三个不同维度的情感冲突：伦理困境、时空对话与记忆见证，探索知识传承中的人性光辉。",
    "styleGuide": "采用冷静克制的影像风格，以实验室的精密美学与档案室的厚重质感形成视觉对比。色彩从早期的单色调逐渐过渡到现代的丰富色彩，象征学术发展。避免特效，依靠实景光影营造氛围。",
    "background": "跨越七十年的校园时空，从1952年建校初期的简陋实验室到当代现代化校园，展现中国高等教育发展的微观史。",
    "characters": [
      {
        "id": "char_001",
        "name": "陈教授",
        "role": "主角",
        "description": "45岁化学教授，严谨理性却在历史发现面前陷入伦理挣扎"
      },
      {
        "id": "char_002", 
        "name": "林研究生",
        "role": "主角",
        "description": "25岁理工女，最初只为学位而研究，却在时空对话中找到科研初心"
      },
      {
        "id": "char_003",
        "name": "老校工李伯",
        "role": "主角",
        "description": "72岁校园守护者，沉默寡言却见证了整个学校的发展历程"
      }
    ],
    "acts": [
      {
        "actNumber": 1,
        "scenes": ["发现异常档案/触发时间异常/回忆初到校园", "伦理质疑初现/跨时空首次接触/发现神秘门锁"]
      },
      {
        "actNumber": 2, 
        "scenes": ["实验重现危机/理念冲突加剧/钥匙背后的故事", "道德抉择时刻/价值认知转变/打开尘封记忆"]
      },
      {
        "actNumber": 3,
        "scenes": ["新的研究方向确立/时空对话终结/校园全景展现", "传承的意义升华/个人成长完成/历史与现实的融合"]
      }
    ]
  },
  "rawText": "序 言 华东理工大学原名华东化工学院，1952年由交通大学、震旦大学、大同大学、东吴大学、江南大学等高校化工系合并创建，是新中国最早的以化工为特色的高等学校，1960年被确定为教育部直属全国重点大学，1993年改为现名，1996年成为国家“211工程”重点建设高校，2017年入选国家“双一流”建设高校。 在创业、求索、发展、图强的奋斗历程中，学校遵循“勤奋求实、励志明德”的校训，以“培育英才、服务社会、奉献人类”为使命，坚持“以人为本、注重过程、传承创新”的办学理念，秉承“脚踏实地、大气谦和”的精神品格，培育笃行实干的校风、博学严谨的教风、乐学善思的学风，形成了“开拓进取、自强不息、知行合一、追求卓越”的大学文化。"
}

